const KIT_KEY = 'kit.current'
const THEMES = ['brand-blue', 'brand-teal', 'brand-graphite']
lumen.ui.onRender(async (root) => {
  const kit = (await lumen.storage.get(KIT_KEY)) ?? { primary: '#1F6FEB', secondary: '#22B8CF' }
  lumen.ui.setTitle(lumen.i18n.t('panel.title'))
  const button = lumen.ui.el('button', { text: lumen.i18n.t('apply') })
  button.addEventListener('click', () => applyBrand(kit))
  root.append(button)
})
async function applyBrand(kit) {
  const nearest = nearestTheme(kit.primary) // 由 kit.primary 与主题 accent 的 RGB 距离选出
  await lumen.deck.transaction('brandguard.apply', () => lumen.deck.applyTheme(nearest))
}
